// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.reminderimport com.roshan.persona.productivity.alarm.EncryptedData/** * NOUS — Reminder Data Models (Module 14 v1.2 — Step 14.2). * * Data structures for reminders (WorkManager-backed — NOT AlarmManager). * Reminder body (the user's note text) is stored as encrypted Base64 — * never as plaintext, even in memory beyond the brief decrypt window. *//** * A scheduled reminder (REAL WorkManager OneTimeWorkRequest). * * @property id            unique reminder ID (used as WorkManager tag). * @property label         short label shown in the notification title. * @property triggerAtMs   epoch milliseconds when the reminder fires. * @property encryptedBody AES-GCM encrypted body (Base64 IV + ciphertext). *                         Null for label-only reminders. * @property status        current [ReminderStatus]. * @property snoozeCount   how many times the user has snoozed this reminder. * @property maxSnoozeCount hard ceiling — after this, snooze is rejected. * @property createdAtMs   when the reminder was created. */data class ReminderInfo(    val id: String,    val label: String,    val triggerAtMs: Long,    val encryptedBody: EncryptedData? = null,    val status: ReminderStatus = ReminderStatus.SCHEDULED,    val snoozeCount: Int = 0,    val maxSnoozeCount: Int = DEFAULT_MAX_SNOOZE,    val createdAtMs: Long = System.currentTimeMillis(),) {    /** Time remaining until reminder fires (milliseconds). */    fun remainingMs(): Long = (triggerAtMs - System.currentTimeMillis()).coerceAtLeast(0)    /** True if the reminder time has passed. */    val hasFired: Boolean get() = System.currentTimeMillis() >= triggerAtMs    /** True if the user can still snooze this reminder. */    val canSnooze: Boolean get() = snoozeCount < maxSnoozeCount    /** Human-readable time string (e.g., "3:00 PM, Mon"). */    val displayTime: String        get() {            val sdf = java.text.SimpleDateFormat("h:mm a, EEE", java.util.Locale.getDefault())            return sdf.format(java.util.Date(triggerAtMs))        }    companion object {        /** Default max snooze count (prevents infinite snoozing). */        const val DEFAULT_MAX_SNOOZE = 3        /** Default snooze duration (5 minutes). */        const val DEFAULT_SNOOZE_MS = 5 * 60 * 1000L    }}/** * Lifecycle status of a reminder. */enum class ReminderStatus(val displayName: String) {    /** Reminder is scheduled and waiting to fire. */    SCHEDULED("Scheduled"),    /** Reminder has fired (notification shown). */    FIRED("Fired"),    /** Reminder was snoozed by the user (re-scheduled with new trigger time). */    SNOOZED("Snoozed"),    /** Reminder was cancelled by the user. */    CANCELLED("Cancelled"),}/** * Snooze options for a reminder. * * @property snoozeMs       how long to delay before re-firing. * @property maxSnoozeCount hard ceiling on snooze count. */data class SnoozeOptions(    val snoozeMs: Long = ReminderInfo.DEFAULT_SNOOZE_MS,    val maxSnoozeCount: Int = ReminderInfo.DEFAULT_MAX_SNOOZE,)/** * Result of reminder operations (sealed class for async returns). * * Mirrors [com.roshan.persona.productivity.alarm.AlarmResult] for consistency * across the productivity stack. */sealed interface ReminderResult<out T> {    data class Success<T>(val data: T, val spokenMessage: String) : ReminderResult<T>    data class Failure(val error: String, val spokenMessage: String) : ReminderResult<Nothing>    data class NeedsPermission(val permissions: List<String>, val spokenMessage: String) : ReminderResult<Nothing>}// ═══════════════════════════════════════════════════════════════════════════// Reminder Store (in-memory for v1 — encrypted Room DB in production)// ═══════════════════════════════════════════════════════════════════════════/** * Reminder Store — manages reminder state (active/fired/snoozed list). * * Production: encrypted Room database (SQLCipher via Module 12, when available). * Current:    in-memory map (sufficient for v1 — WorkManager survives reboots *             and reapplies scheduled work automatically). * * The body field is ALWAYS stored as [EncryptedData] — never as plaintext. */class ReminderStore {    private val reminders = mutableMapOf<String, ReminderInfo>()    /** Store a new reminder (or replace an existing one with the same ID). */    fun put(reminder: ReminderInfo) {        reminders[reminder.id] = reminder    }    /** Get a reminder by ID. */    fun getById(id: String): ReminderInfo? = reminders[id]    /** Get all reminders that are still scheduled (not fired/cancelled). */    fun getAllActive(): List<ReminderInfo> =        reminders.values.filter { it.status == ReminderStatus.SCHEDULED && !it.hasFired }    /** Get all reminders regardless of status. */    fun getAll(): List<ReminderInfo> = reminders.values.toList()    /** Get the next reminder to fire (earliest trigger time among active). */    fun getNextActive(): ReminderInfo? = getAllActive().minByOrNull { it.triggerAtMs }    /** Delete a reminder by ID. */    fun deleteById(id: String): Boolean = reminders.remove(id) != null    /** Mark a reminder as fired. */    fun markAsFired(id: String) {        reminders[id]?.let { reminders[id] = it.copy(status = ReminderStatus.FIRED) }    }    /** Mark a reminder as snoozed + bump snooze count + new trigger time. */    fun markAsSnoozed(id: String, newTriggerMs: Long) {        reminders[id]?.let {            reminders[id] = it.copy(                status = ReminderStatus.SCHEDULED,                triggerAtMs = newTriggerMs,                snoozeCount = it.snoozeCount + 1,            )        }    }    /** Mark a reminder as cancelled. */    fun markAsCancelled(id: String) {        reminders[id]?.let { reminders[id] = it.copy(status = ReminderStatus.CANCELLED) }    }    /** Count of active (still-scheduled) reminders. */    fun activeCount(): Int = getAllActive().size    /** Clear all reminders (used by tests). */    fun clear() = reminders.clear()}